function saveVarRaw(side,entryId){const panel=document.querySelector('[data-vars-panel]');const ta=panel?.querySelector('[data-vars-raw]');if(!panel||!ta||!side||!entryId)return;const prompt=byId(side).get(entryId);if(!prompt){pcmToastr.error('变量条目不存在');return;}pushUndo({type:'edit',side,id:entryId,before:clone(prompt),modifiedBefore:[...state.modified[side]]});prompt.content=ta.value;state.modified[side].add(entryId);state.dirty[side]=true;rebuildCache();renderList(side);renderVarPanel(side,entryId);pcmToastr.success('条目原文已保存（可用顶部「撤回」恢复）');}
function renderRefPanel(side){const panel=document.querySelector('[data-vars-panel]');if(!panel)return;panel.dataset.side=side;panel.dataset.view='ref';panel.querySelector('h3').textContent='引用变量 · '+(side==='old'?'旧版':'新版');const vtb=panel.querySelector('[data-vars-toggle]');if(vtb)vtb.textContent='切换至获取变量';const body=panel.querySelector('[data-vars-body]');body.replaceChildren();
const entries=varEntries(side);if(!entries.length){body.append(el('div','pcm-vars-stats','当前预设没有含 {{setvar}} 的变量条目'));panel.classList.add('open');return;}
const entry=entries[0];const prompt=byId(side).get(entry.id);if(!prompt){panel.classList.add('open');return;}panel.dataset.refId=entry.id;
const unref=unreferencedVars(side,entry.id);
const bar=el('div','pcm-vars-bar');bar.append(el('span','pcm-vars-label','获取变量条目:'));bar.append(el('code','pcm-vars-entry-name',entry.name));const saveIcon=iconBtn('vars-save-ref','保存条目内容（可用顶部「撤回」恢复）',PCM_ICONS.save);saveIcon.dataset.side=side;saveIcon.dataset.entryId=entry.id;saveIcon.classList.add('pcm-vars-save');bar.append(saveIcon);body.append(bar);
body.append(el('div','pcm-vars-stats','有 '+unref.length+' 个变量已经定义但未被引用'));
if(unref.length){const chipsWrap=el('div','pcm-vars-refchips');chipsWrap.append(el('div','pcm-vars-label','已经定义但未被引用的变量：'));const chips=el('div','pcm-vars-chips');for(const v of unref)chips.append(el('code','',v));chipsWrap.append(chips);body.append(chipsWrap);body.append(el('div','pcm-vars-stats','以上变量已在当前获取变量条目中定义，但整个预设没有 getvar 或 getglobalvar 读取；原文中已用橘红标出。编辑后点右上角保存图标写回条目，可用顶部「撤回」恢复'));}
const wrap=el('div','pcm-editwrap live');const bd=el('pre','pcm-diff-backdrop');bd.setAttribute('aria-hidden','true');const ta=el('textarea');ta.dataset.refContent='';ta.value=String(prompt.content||'');wrap.append(bd,ta);body.append(wrap);
const unrefSet=new Set(unref.map(v=>v.trim()));
const align=(a,b)=>{const cs=getComputedStyle(a);b.style.fontFamily=cs.fontFamily;b.style.fontSize=cs.fontSize;b.style.lineHeight=cs.lineHeight;b.style.letterSpacing=cs.letterSpacing;b.style.paddingTop=(parseFloat(cs.paddingTop)+parseFloat(cs.borderTopWidth))+'px';b.style.paddingRight=(parseFloat(cs.paddingRight)+parseFloat(cs.borderRightWidth))+'px';b.style.paddingBottom=(parseFloat(cs.paddingBottom)+parseFloat(cs.borderBottomWidth))+'px';b.style.paddingLeft=(parseFloat(cs.paddingLeft)+parseFloat(cs.borderLeftWidth))+'px';};align(ta,bd);
const paint=()=>{const c=String(ta.value);const reSet=/\{\{(?:setvar|setglobalvar)::([^:}]+)::([\s\S]*?)\}\}/g;const frag=document.createDocumentFragment();let last=0;let m;while((m=reSet.exec(c))){if(m.index>last)frag.append(document.createTextNode(c.slice(last,m.index)));const hit=unrefSet.has(m[1].trim());const sp=el('span',hit?'refhit':'refplain');sp.textContent=m[0];frag.append(sp);last=m.index+m[0].length;}if(last<c.length)frag.append(document.createTextNode(c.slice(last)));bd.replaceChildren(frag);};
paint();let timer=null;const deb=()=>{clearTimeout(timer);timer=setTimeout(paint,200);};ta.addEventListener('input',deb);ta.addEventListener('scroll',()=>{bd.scrollTop=ta.scrollTop;bd.scrollLeft=ta.scrollLeft;});if(window.requestIdleCallback)requestIdleCallback(paint,{timeout:200});else setTimeout(paint,0);
panel.classList.add('open');}
function saveRefPanel(side,entryId){const panel=document.querySelector('[data-vars-panel]');const ta=panel?.querySelector('[data-ref-content]');if(!panel||!ta||!side||!entryId)return;const prompt=byId(side).get(entryId);if(!prompt){pcmToastr.error('条目不存在');return;}pushUndo({type:'edit',side,id:entryId,before:clone(prompt),modifiedBefore:[...state.modified[side]]});prompt.content=ta.value;state.modified[side].add(entryId);state.dirty[side]=true;rebuildCache();renderList(side);renderRefPanel(side,entryId);pcmToastr.success('条目内容已保存（可用顶部「撤回」恢复）');}

