function iconBtn(action,title,svg,cls){const b=el('button','menu_button pcm-icon-btn'+(cls?' '+cls:''));b.type='button';b.dataset.action=action;b.title=title;b.setAttribute('aria-label',title);b.innerHTML=svg;return b;}
let selectedProjectId=null;
function toggleProjList(force){const dropEl=document.querySelector('.pcm-proj-drop');if(!dropEl)return;const open=force!==undefined?force:!dropEl.classList.contains('open');if(open)refreshProjList();dropEl.classList.toggle('open',open);}
async function refreshProjList(){const list=document.querySelector('[data-proj-list]');if(!list)return;let projects=[];try{projects=await listProjects();}catch{return;}list.replaceChildren();if(!projects.length){list.append(el('div','pcm-proj-empty','暂无已保存项目'));return;}for(const p of projects){const item=el('button','pcm-proj-item');item.type='button';item.textContent=p.name+' · '+new Date(p.updatedAt).toLocaleString();item.title=p.name;item.addEventListener('click',()=>{const input=document.querySelector('[data-project-name]');if(input)input.value=p.name;selectedProjectId=p.id;toggleProjList(false);});list.append(item);}}
document.addEventListener('click',event=>{if(!event.target.closest?.('.pcm-proj-drop'))toggleProjList(false);});
async function startApplication(){
  await host.ready();
  await loadUiPrefs();
  watchTavernPresetEvents();
  host.on('open',()=>{try{const dialog=shell();openDialogSafe(dialog);restorePanelState(dialog);}catch(error){console.error('[preset-compare-migrator] init failed',error);pcmToastr.error(error.message,APP_TITLE+'启动失败');}});
  host.on('host-closed',()=>{const dialog=document.getElementById(APP_ID+'-dialog');if(!dialog)return;if(dialog.open)dialog.close();else destroyPanel(dialog);});
  await host.notify('ready');
}
startApplication().catch(error=>console.error('[preset-compare-migrator] bootstrap failed',error));
